#!/usr/bin/env node
/**
 * Generates packages/contracts/src/data/municipality-codes.ts from
 * piuccio/open-data-jp-municipalities (JIS X 0402 municipality codes).
 *
 *   node scripts/tools/generate-municipality-codes.mjs
 *
 * The generated file is committed so the Worker bundle needs no network at
 * build time. Re-run when municipal mergers/renames need to be reflected.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const SOURCE_URL =
  'https://raw.githubusercontent.com/piuccio/open-data-jp-municipalities/master/municipalities.json';

const outFile = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../packages/contracts/src/data/municipality-codes.ts',
);

const res = await fetch(SOURCE_URL);
if (!res.ok) throw new Error(`failed to fetch municipalities: HTTP ${res.status}`);
const rows = await res.json();
if (!Array.isArray(rows)) throw new Error('unexpected response shape');

// JIS X 0402 codes are 6 digits (5-digit code + check digit); assets store the
// 5-digit form (municipality_code char(5)).
const entries = rows
  .filter((row) => row.name_kanji?.trim() && /^\d{6}$/.test(row.code ?? ''))
  .map((row) => ({
    prefecture: row.prefecture_kanji.trim(),
    name: row.name_kanji.trim(),
    code: row.code.slice(0, 5),
  }))
  .filter((entry) => /^\d{5}$/.test(entry.code))
  .filter(
    (entry, index, all) =>
      all.findIndex((other) => other.code === entry.code && other.name === entry.name) === index,
  )
  .sort((a, b) => a.code.localeCompare(b.code));

const body = `/**
 * Auto-generated by scripts/tools/generate-municipality-codes.mjs — do not edit.
 * Source: piuccio/open-data-jp-municipalities (JIS X 0402 市区町村コード).
 * 更新時: node scripts/tools/generate-municipality-codes.mjs
 */
export interface MunicipalityCodeEntry {
  /** 都道府県名（例: 北海道） */
  prefecture: string;
  /** 市区町村名（例: 札幌市） */
  name: string;
  /** 5桁市区町村コード */
  code: string;
}

export const MUNICIPALITY_CODES: readonly MunicipalityCodeEntry[] = [
${entries.map((e) => `  { prefecture: '${e.prefecture}', name: '${e.name}', code: '${e.code}' },`).join('\n')}
];
`;

await mkdir(path.dirname(outFile), { recursive: true });
await writeFile(outFile, body, 'utf8');
console.log(`✅ wrote ${entries.length} municipalities -> ${outFile}`);
